actions.script:
if (!draftProject) return
const L = (text) => ec.l10n.localize(text)
const header = ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectHeader').parameters({workEffortId: workEffortId}).call()?.header || {}
const settings = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings').parameters({workEffortId: workEffortId}).call()?.settings || {}
const team = ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectTeam').parameters({workEffortId: workEffortId}).call() || {}
const rates = Array.from(ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectRates').parameters({workEffortId: workEffortId}).call()?.rateList || [])
const moduleNames = {backlog: 'Backlog and sprints', requests: 'Requests', code: 'Code', docs: 'Docs', time: 'Time', money: 'Money', client: 'Client access'}
const repos = Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitRepository').condition('workEffortId', workEffortId)
        .conditionDate('fromDate', 'thruDate', null).list()).map((row) => row.repositoryId)
const bases = {TimeAndMaterials: 'Time and materials', FixedPrice: 'Fixed price', Milestones: 'By milestones', NotBilled: 'Not billed'}
const hours = (value) => value == null ? '' : ec.l10n.format(value, '#,##0.##')
reviewList = [
    ['Project', (header.workEffortName || workEffortId) + ' (' + workEffortId + ')', '../Start'],
    ['Purpose', header.purposeLabel, '../Start'], ['Client', header.clientName || L('Internal'), '../Start'], ['Manager', header.managerName, '../Start'],
    ['Start', header.startText, '../Start'], ['Target date', header.dueText, '../Start'],
    ['Who sees it', draftProject.visibilityEnumId === 'WevWorkGroup' ? L('Its members only') : L('Everyone in the organization'), '../Start'],
    ['Members', Array.from(team.memberList || []).map((row) => row.name + ' (' + row.roleText + ')').join(', ') || L('None yet'), '../Team'],
    ['Modules', String(settings.WstModules || '').split(',').filter((key) => key).map((key) => L(moduleNames[key] || key)).join(', ') || L('None'), '../Modules'],
    ['Estimates in', settings.WstEstimateUnit === 'points' ? L('Story points') : L('Hours'), '../Modules'],
    ['Work item flow', draftProject.statusFlowId === 'WorkEffortDevelopment' ? L('Development') : L('Default'), '../Modules'],
    ['Repository', repos.join(', ') || L('None'), '../Modules'], ['Documentation', settings.WstDocsWikiSpace || L('None'), '../Modules'],
    ['Billing basis', L(bases[settings.WstBillingBasis] || 'Not set'), '../Money'],
    ['Hours budget', draftProject.totalTimeAllowed != null ? hours(draftProject.totalTimeAllowed) + ' h' : L('None'), '../Money'],
    ['Client budget', draftProject.totalClientCostAllowed != null ? ec.l10n.formatCurrency(draftProject.totalClientCostAllowed, draftProject.costUomId || 'USD') : L('None'), '../Money'],
    ['Rates', rates.map((rate) => rate.appliesText + ' ' + rate.amountText).join(', ') || L('None of its own'), '../Money']]
        .map(([label, value, step]) => ({label: L(label), value: value || '—', step: step}))
